// Bundles the server dashboard page into a single script for the webview: the CommonJS modules
// compiled by `tsc -p tsconfig.page.json` (out/page-modules) are wrapped in functions of a tiny
// module loader, starting from the entry point, following the relative `require` calls.
// The page must not depend on other modules (e.g. vscode-jsonrpc: the page only imports types of
// the protocol, erased by the compilation): any other `require` fails the build.
// Usage: node scripts/bundle-page.js
// Output: out/media/dashboard.js, and the Codicons (CSS, font, licenses) in out/media/codicons

'use strict';

const fs = require('fs');
const path = require('path');

const extensionRoot = path.resolve(__dirname, '..');
const modulesRoot = path.join(extensionRoot, 'out', 'page-modules');
const entry = 'ui/dashboard/page/dashboardPage';
const output = path.join(extensionRoot, 'out', 'media', 'dashboard.js');

/** @type {Map<string, string>} module id (path relative to modulesRoot, without extension) -> code */
const modules = new Map();

function addModule(id) {
  if (modules.has(id)) {
    return;
  }
  const file = path.join(modulesRoot, `${id}.js`);
  if (!fs.existsSync(file)) {
    throw new Error(`Module not found: ${file}`);
  }
  modules.set(id, ''); // Cycles
  let code = fs.readFileSync(file, 'utf8').replace(/^\/\/# sourceMappingURL=.*$/m, '');
  code = code.replace(/\brequire\((["'])([^"']+)\1\)/g, (_, quote, specifier) => {
    if (!specifier.startsWith('.')) {
      throw new Error(`${id}: the dashboard page can't depend on "${specifier}" (only relative imports, types of other modules)`);
    }
    const dependency = path.posix.normalize(path.posix.join(path.posix.dirname(id), specifier));
    addModule(dependency);
    return `require(${JSON.stringify(dependency)})`;
  });
  modules.set(id, code);
}

addModule(entry);

const parts = [
  '// Generated by scripts/bundle-page.js from src/ui/dashboard (do not edit).',
  '(function () {',
  '  "use strict";',
  '  const definitions = {};',
  '  const cache = {};',
  '  function require(id) {',
  '    if (!cache[id]) {',
  '      const module = { exports: {} };',
  '      cache[id] = module;',
  '      definitions[id](module, module.exports, require);',
  '    }',
  '    return cache[id].exports;',
  '  }',
];
for (const [id, code] of modules) {
  parts.push(`  definitions[${JSON.stringify(id)}] = function (module, exports, require) {`, code, '  };');
}
parts.push(`  require(${JSON.stringify(entry)});`, '})();', '');

fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, parts.join('\n'));
console.log(`Bundled ${modules.size} modules into ${path.relative(extensionRoot, output)}`);

// The Codicons (icon font of VS Code, dev dependency "@vscode/codicons"), loaded by the page:
// copied with their license (the font is licensed under CC BY 4.0, the CSS under MIT).
const codiconsSource = path.join(extensionRoot, 'node_modules', '@vscode', 'codicons');
const codiconsOutput = path.join(path.dirname(output), 'codicons');
fs.mkdirSync(codiconsOutput, { recursive: true });
for (const [from, to] of [
  ['dist/codicon.css', 'codicon.css'],
  ['dist/codicon.ttf', 'codicon.ttf'],
  ['LICENSE', 'LICENSE'],
  ['LICENSE-CODE', 'LICENSE-CODE'],
]) {
  const source = path.join(codiconsSource, from);
  if (!fs.existsSync(source)) {
    throw new Error(`${source} not found: run "npm install"`);
  }
  fs.copyFileSync(source, path.join(codiconsOutput, to));
}
console.log(`Copied the Codicons into ${path.relative(extensionRoot, codiconsOutput)}`);
